/**
 * ODE checks: representative equations for SymPy's dsolve hints, compared
 * with the output of SymPy (compat/ode-checks.json, generated by
 * compat/gen-ode-checks.py). Reported separately in compat/REPORT.md.
 */

import { readFileSync } from 'node:fs';
import * as sj from '../packages/symjs/src';
import { Expr } from '../packages/symjs/src';

type OdeCheck = { hint: string; eq: string; ics?: [string, string][]; expected: string };
/** exact: same printed solution as SymPy; equivalent: a different form that solves the ODE with as many constants. */
export type OdeCheckResult = OdeCheck & { got: string; pass: boolean; exact: boolean };

/** Number of distinct integration constants C1, C2, ... in a printed solution. */
export const constantCount = (s: string) => new Set(s.match(/\bC\d+\b/g) ?? []).size;

/**
 * SymPy checkodesol for explicit solutions of an equation or a system:
 * substitute every solved function (and its derivatives) and evaluate the
 * residuals at test points.
 */
export function solvesOdeSystem(eqs: readonly Expr[], x: sj.Sym, sols: readonly Expr[]): boolean {
  if (!sols.length) return false;
  const pairs: [Expr, Expr][] = [];
  for (const s of sols) {
    if (!(s instanceof sj.Rel) || !(s.lhs instanceof sj.UndefFn) || s.rhs.has(s.lhs)) return false;
    pairs.push([s.lhs, s.rhs]);
  }
  const order = 6;
  for (const eq of eqs) {
    let r = eq instanceof sj.Rel ? sj.sub(eq.lhs, eq.rhs) : eq;
    for (const [fx, rhs] of pairs) {
      for (let k = order; k >= 1; k--) r = sj.xreplace(r, [[sj.derivative(fx, [[x, k]]), sj.diff(rhs, x, k)]]);
    }
    r = sj.xreplace(r, pairs);
    const syms = [...sj.freeSymbols(r)];
    let ok = 0;
    for (const t of [0.37, 0.83, 1.41]) {
      const rep = syms.map((v, i) => [v, sj.float(v.name === x.name ? t : 0.5 + 0.3 * i + t / 7)] as [Expr, Expr]);
      try {
        const c = sj.evalf(sj.doit(sj.xreplace(r, rep)), 20).toComplex();
        if (!Number.isFinite(c.re) || !Number.isFinite(c.im)) continue;
        if (Math.hypot(c.re, c.im) > 1e-8) return false;
        ok++;
      } catch {
        continue;
      }
    }
    if (ok < 2) return false;
  }
  return true;
}

function solvesOde(eq: Expr, fx: Expr, x: sj.Sym, sols: Expr[]): boolean {
  return sols.every((s) => s instanceof sj.Rel && s.lhs.key === fx.key) && solvesOdeSystem([eq], x, sols);
}

export function runOdeChecks(): OdeCheckResult[] {
  const data = JSON.parse(readFileSync(new URL('./ode-checks.json', import.meta.url), 'utf8')) as { checks: OdeCheck[] };
  const f = sj.SymFunction('f');
  const x = new sj.Sym('x');
  const fx = f(x);
  return data.checks.map((c) => {
    let got: string;
    let solves = false;
    try {
      const eq = sj.parse(c.eq);
      const ics = c.ics?.map(([k, v]) => [icsKey(k, fx, x), sj.parse(v)] as [Expr, Expr]);
      const r = sj.dsolve(eq, fx, ics ? { ics } : {});
      const sols: Expr[] = Array.isArray(r) ? r.flat() : [r];
      got = Array.isArray(r) ? `[${r.map(String).join(', ')}]` : String(r);
      solves = !c.ics && solvesOde(eq, fx, x, sols) && constantCount(got) === constantCount(c.expected);
    } catch (e) {
      got = `error: ${(e as Error).message}`;
    }
    const exact = got === c.expected;
    return { ...c, got, exact, pass: exact || solves };
  });
}

/** f(0) or Subs(Derivative(f(x), x), x, 0) written as SymPy prints them. */
function icsKey(k: string, fx: Expr, x: sj.Sym): Expr {
  const m = /^Subs\(Derivative\(f\(x\), (.*)\), x, (.*)\)$/.exec(k);
  if (m) {
    const order = m[1]!.split(',').length;
    const at = sj.parse(m[2]!);
    return sj.derivative(sj.SymFunction('f')(at), [[x, order]]);
  }
  void fx;
  return sj.parse(k);
}
